#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "syrk.h"


/* Array initialization. */
static
void init_array(int n, int m,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < n; i++)
    for (j = 0; j < m; j++)
      A[i][j] = (DATA_TYPE) ((i*j+1)%n) / n;
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      C[i][j] = (DATA_TYPE) ((i*j+2)%m) / m;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_syrk[[gnu::flatten, gnu::noinline]](int n, int m,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j, k;

  /* Create local restrict-qualified views of the 2D arrays.
     This gives the compiler stronger aliasing guarantees and
     enables better vectorization and load/store scheduling. */
  DATA_TYPE (*restrict C_)[n] = C;
  DATA_TYPE (*restrict A_)[m] = A;

  /* Cache the (possibly macro-based) loop bounds in local consts.
     This avoids re-evaluating macros and helps the optimizer. */
  const int n_pb = _PB_N;
  const int m_pb = _PB_M;

  /* BLAS PARAMS
   * TRANS = 'N'
   * UPLO  = 'L'
   * =>  Form  C := alpha*A*A**T + beta*C.
   * A is NxM
   * C is NxN
   *
   * Parallelization:
   *  - Each iteration of the outer i-loop updates only row i
   *    of the lower triangular part of C (C[i][0..i]).
   *  - Rows are independent, so we safely parallelize over i.
   *
   * Locality / compute optimizations:
   *  - Row pointer Ci hoisted outside inner loops to reduce address
   *    arithmetic and improve cache locality.
   *  - For each (i,k) pair we precompute aik = alpha * A[i][k]
   *    once and reuse it for all j in [0..i].
   *  - Inner j-loops are annotated with omp simd to encourage
   *    vectorization when OpenMP SIMD is enabled; without OpenMP
   *    these pragmas are ignored by most compilers.
   */

#pragma scop
  /* Parallelize across rows of C.  If OpenMP is not enabled,
     this pragma is ignored and the code runs sequentially. */
#pragma omp parallel for private(j,k) schedule(static)
  for (i = 0; i < n_pb; i++) {
    /* Pointer to current row of C for better locality. */
    DATA_TYPE *restrict Ci = C_[i];

    /* Scale the lower triangular part of row i by beta. */
#pragma omp simd
    for (j = 0; j <= i; j++)
      Ci[j] *= beta;

    /* SYRK update: C[i][j] += alpha * A[i][k] * A[j][k] for j <= i.
       For fixed (i,k) we load A[i][k] once, multiply by alpha,
       and reuse the result across all j. */
    for (k = 0; k < m_pb; k++) {
      const DATA_TYPE aik = alpha * A_[i][k];

#pragma omp simd
      for (j = 0; j <= i; j++)
        Ci[j] += aik * A_[j][k];
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,N,M,n,m);

  /* Initialize array(s). */
  init_array (n, m, &alpha, &beta, POLYBENCH_ARRAY(C), POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_syrk (n, m, alpha, beta, POLYBENCH_ARRAY(C), POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
