#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>
#include <omp.h>  /* Added for parallelization of the main kernel */

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "syrk.h"


/* Array initialization. */
static
void init_array(int n, int m,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;

  /* Hoist divisions out of the loops to reduce the number of
     expensive division operations. The resulting arithmetic is
     mathematically identical to the original code. */
  DATA_TYPE inv_n = (DATA_TYPE)1.0 / (DATA_TYPE)n;
  DATA_TYPE inv_m = (DATA_TYPE)1.0 / (DATA_TYPE)m;

  for (i = 0; i < n; i++)
    for (j = 0; j < m; j++)
      A[i][j] = ((DATA_TYPE)((i * j + 1) % n)) * inv_n;

  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      C[i][j] = ((DATA_TYPE)((i * j + 2) % m)) * inv_m;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_syrk [[gnu::flatten, gnu::noinline]] (int n, int m,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j, k;

  /* BLAS PARAMS
   * TRANS = 'N'
   * UPLO  = 'L'
   * => Form  C := alpha*A*A**T + beta*C.
   * A is NxM
   * C is NxN
   *
   * Optimizations applied compared to the baseline version:
   * 1) Fused the separate "scale by beta" loop and the rank-k update
   *    into a single nest working on one C(i,j) element at a time.
   *    Each C(i,j) is now loaded and stored exactly once instead of
   *    once per k-iteration, which greatly reduces memory traffic.
   *
   * 2) Reordered the computation so that for each (i,j) with j <= i
   *    we compute the full dot product over k in a tight inner loop.
   *    This exposes a simple, contiguous inner loop that the compiler
   *    can efficiently auto-vectorize.
   *
   * 3) Introduced restrict-qualified local aliases for the 2D arrays,
   *    describing to the compiler that A and C do not alias. This
   *    enables better vectorization and instruction scheduling.
   *
   * 4) Parallelized the outer i-loop using OpenMP. Each iteration of
   *    i updates a distinct row of C and only reads from A, so there
   *    are no data races.
   *
   * The mathematical operation remains:
   *   C(i,j) <- beta * C(i,j) + alpha * sum_k A(i,k) * A(j,k)
   * for 0 <= j <= i < N (lower triangular part of C).
   */

  /* VLA dimensions for local, restrict-qualified views of the matrices.
     These dimensions match the dynamic sizes used when allocating the
     arrays in main. */
  int nn = n;
  int mm = m;

  DATA_TYPE (*restrict C_)[nn] = C;
  DATA_TYPE (*restrict A_)[mm] = A;

#pragma scop
  /* Parallelize across rows of C. Each iteration updates only C_[i][0..i]
     and reads from A_, so iterations are independent. */
#pragma omp parallel for private(j,k) schedule(static)
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *restrict Ci = C_[i];
    DATA_TYPE *restrict Ai = A_[i];

    /* Only the lower triangular part (j <= i) is updated. */
    for (j = 0; j <= i; j++) {
      DATA_TYPE *restrict Aj = A_[j];

      /* Compute dot product between row i and row j of A over k.
         The inner loop is contiguous in k for both Ai and Aj, which
         is cache-friendly and vectorization-friendly. */
      DATA_TYPE dot = (DATA_TYPE)0;
      for (k = 0; k < _PB_M; k++) {
        dot += Ai[k] * Aj[k];
      }

      /* Apply the SYRK update: C(i,j) = beta*C(i,j) + alpha*dot. */
      Ci[j] = beta * Ci[j] + alpha * dot;
    }
  }
#pragma endscop

}


