   * and reads A[0..i][0..mi-1], so iterations are independent. */
#pragma omp parallel for private(j,k) schedule(static)
  for (i = 0; i < ni; i++) {
    DATA_TYPE       *Ci = C[i];
    const DATA_TYPE *Ai = A[i];

    /* Only the lower triangular part is updated: j <= i.  For each (i,j),
     * compute:
     *   C[i][j] = beta * C[i][j] + alpha * sum_k (A[i][k] * A[j][k])
