       * Blocking does NOT change the order in which k-contributions
       * are accumulated for a given (i,j): k still runs from 0 to mi-1
       * in ascending order, just partitioned into contiguous chunks. */
      for (int kk = 0; kk < mi; kk += SYRK_K_BLOCK) {
        const int kend = (kk + SYRK_K_BLOCK < mi) ? (kk + SYRK_K_BLOCK) : mi;

        /* Innermost loop over contiguous k-range – good for SIMD. */
        #pragma omp simd
        for (k = kk; k < kend; k++) {
          sum += alpha_ * Ai[k] * Aj[k];
        }
      }
#else
      /* Simple, straight k-loop (still with good spatial locality). */
      #pragma omp simd
      for (k = 0; k < mi; k++) {
        sum += alpha_ * Ai[k] * Aj[k];
      }
#endif

      Ci[j] = sum;
    }
  }

