#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>
#include <omp.h>  /* Added for OpenMP-based parallelization and SIMD hints */

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "syrk.h"

/* --------------------------------------------------------------------------
 * Tunable constants for this kernel.
 *
 * SYRK_OMP_MIN_N:
 *   Minimal problem size (in N) above which we enable multi-threading
 *   for the main kernel. For very small N, the parallel overhead can
 *   dominate; this threshold allows tuning for a particular machine.
 * -------------------------------------------------------------------------- */
#ifndef SYRK_OMP_MIN_N
# define SYRK_OMP_MIN_N 64
#endif


/* Array initialization. */
static
void init_array(int n, int m,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < n; i++)
    for (j = 0; j < m; j++)
      A[i][j] = (DATA_TYPE) ((i*j+1)%n) / n;
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      C[i][j] = (DATA_TYPE) ((i*j+2)%m) / m;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_syrk[[gnu::flatten, gnu::noinline]](int n, int m,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j, k;

  (void)n; /* n and m are used via PolyBench loop-bound macros; silence warnings. */
  (void)m;

  // BLAS PARAMS
  // TRANS = 'N'
  // UPLO  = 'L'
  // =>  Form  C := alpha*A*A**T + beta*C.
  // A is NxM
  // C is NxN

  /*
   * Optimizations over the baseline implementation:
   *
   * 1. Hoist invariant computations:
   *      - For each (i, k) pair, alpha*A[i][k] is invariant with respect to j.
   *        We compute it once as `tmp` and reuse it in the inner j-loop.
   *
   * 2. Improve memory access and enable vectorization:
   *      - Use local row pointers (Ci, Ai) marked as `restrict` to
   *        help the compiler with alias analysis and reduce address
   *        recalculation for C[i][j] and A[i][k].
   *      - Replace `for (j = 0; j <= i; ++j)` with a form using a
   *        precomputed upper bound (`max_j = i + 1`) to keep the inner
   *        loop canonical and easier to vectorize.
   *      - Add `#pragma omp simd` directives on the innermost j-loops
   *        to explicitly allow SIMD vectorization when possible.
   *
   * 3. Parallelization:
   *      - The outer loop over `i` is embarrassingly parallel:
   *          * Different iterations update disjoint rows of C
   *            (lower triangular entries C[i][0..i]).
   *          * A is read-only.
   *        Hence we parallelize with `#pragma omp parallel for`.
   *      - The `if(_PB_N >= SYRK_OMP_MIN_N)` clause avoids spawning
   *        threads for very small N where overhead can dominate.
   *
   * 4. Semantics:
   *      - The order of operations over (i, j, k) is preserved with
   *        respect to the baseline code, except for allowed changes
   *        in instruction scheduling due to parallelization and SIMD.
   *      - The triangular access pattern (only j <= i) is unchanged.
   *      - C's upper triangular part (j > i) is left untouched, as in
   *        the original kernel.
   */

#pragma scop
#pragma omp parallel for if(_PB_N >= SYRK_OMP_MIN_N) private(j,k) schedule(static)
  for (i = 0; i < _PB_N; i++)
  {
    /* Local row pointers for better locality and fewer address computations.
       `restrict` is safe because different rows of C and A do not alias and
       A and C are distinct arrays. */
    DATA_TYPE *restrict Ci = C[i];
    DATA_TYPE *restrict Ai = A[i];

    const int max_j = i + 1; /* Number of elements in the lower-triangular
                                part of row i (j = 0..i). */

    /* Scale the relevant part of row i of C by beta: C[i][j] *= beta. */
    #pragma omp simd
    for (j = 0; j < max_j; j++)
      Ci[j] *= beta;

    /* SYRK rank-k update:
       C[i][j] += alpha * A[i][k] * A[j][k]  for 0 <= j <= i, 0 <= k < M. */
    for (k = 0; k < _PB_M; k++)
    {
      /* Hoist alpha * A[i][k] out of the inner j-loop. */
      const DATA_TYPE tmp = alpha * Ai[k];

      /* Inner loop is purely element-wise and free of dependencies between
         iterations; we explicitly mark it as vectorizable. */
      #pragma omp simd
      for (j = 0; j < max_j; j++)
        Ci[j] += tmp * A[j][k];
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,N,M,n,m);

  /* Initialize array(s). */
  init_array (n, m, &alpha, &beta, POLYBENCH_ARRAY(C), POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_syrk (n, m, alpha, beta, POLYBENCH_ARRAY(C), POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
